package com.android.systemui.statusbar;
import android.content.*;import android.database.ContentObserver;import android.os.*;import android.provider.Settings;import java.lang.ref.WeakReference;
public final class LunatikBlurConfig {
 static final java.util.WeakHashMap<Object,Float> logicalAlpha=new java.util.WeakHashMap<>();
 public static void rememberAlpha(Object view,float alpha){logicalAlpha.put(view,alpha);}
 public static float animationStartAlpha(Object view,float actual){Float value=logicalAlpha.get(view);return value==null?actual:value;}
 static Context context;static int radius=60,dark=43,mode=3;static WeakReference<Object> utils=new WeakReference<>(null),root=new WeakReference<>(null),scrim=new WeakReference<>(null);static int rawRadius;static boolean opaque;static float scale;static boolean started;
 static synchronized void init(){if(started)return;try{context=(Context)Class.forName("android.app.ActivityThread").getMethod("currentApplication").invoke(null);if(context==null)return;started=true;if(Settings.Global.getString(context.getContentResolver(),"disable_window_blurs")==null)Settings.Global.putInt(context.getContentResolver(),"disable_window_blurs",0);if(Settings.System.getString(context.getContentResolver(),"single_qs_tone_enabled")==null)Settings.System.putInt(context.getContentResolver(),"single_qs_tone_enabled",1);read();ContentObserver o=new ContentObserver(new Handler(Looper.getMainLooper())){public void onChange(boolean self){read();refresh();}};context.getContentResolver().registerContentObserver(Settings.System.getUriFor("lunatik_blur_mode"),false,o);context.getContentResolver().registerContentObserver(Settings.System.getUriFor("lunatik_blur_radius"),false,o);context.getContentResolver().registerContentObserver(Settings.System.getUriFor("lunatik_blur_darkness"),false,o);}catch(Exception e){android.util.Log.w("LunatikBlur","init",e);}}
 static void read(){mode=Math.max(1,Math.min(3,Settings.System.getInt(context.getContentResolver(),"lunatik_blur_mode",Settings.System.getInt(context.getContentResolver(),"lunatik_notification_glass",1)!=0?3:2)));radius=Math.max(0,Math.min(150,Settings.System.getInt(context.getContentResolver(),"lunatik_blur_radius",60)));dark=Math.max(0,Math.min(100,Settings.System.getInt(context.getContentResolver(),"lunatik_blur_darkness",43)));}
 public static int radius(Object u,Object r,int raw,boolean op,float sc){init();utils=new WeakReference<>(u);root=new WeakReference<>(r);rawRadius=raw;opaque=op;scale=sc;return mode==1?raw:Math.round(raw*(radius/82f));}
 public static float effectRadius(float r){init();return mode==1?r:r*(radius/82f);}
 public static void scrim(Object s){init();scrim=new WeakReference<>(s);}
 public static int surfaceTint(Object view){init();android.content.Context c=((android.view.View)view).getContext();boolean night=(c.getResources().getConfiguration().uiMode&48)==32;return night?0xff000000:0xffffffff;}
 public static boolean customEnabled(){init();return mode>1;}
 public static float darkness(float alpha){init();if(mode==1)return alpha;return Math.min(1,alpha*(dark/100f)/(185/255f));}
 static void refresh(){try{Object s=scrim.get();if(s!=null)s.getClass().getMethod("updateScrims").invoke(s);Object u=utils.get(),r=root.get();PowerManager pm=(PowerManager)context.getSystemService(Context.POWER_SERVICE);if(u!=null&&r!=null&&pm.isInteractive())u.getClass().getMethod("applyBlur",Class.forName("android.view.ViewRootImpl"),int.class,boolean.class,float.class).invoke(u,r,rawRadius,opaque,scale);}catch(Exception e){android.util.Log.w("LunatikBlur","refresh",e);}}
}
